package org.zhejianglab.astro;

import com.sun.net.httpserver.HttpServer;
import io.javaoperatorsdk.operator.Operator;
import java.io.IOException;
import java.net.InetSocketAddress;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.zhejianglab.astro.probes.LivenessHandler;
import org.zhejianglab.astro.probes.StartupHandler;
import org.zhejianglab.astro.reconciler.MetadataOperatorFlinkReconciler;
import org.zhejianglab.astro.reconciler.MetadataOperatorJavaReconciler;

public class Runner {

  private static final Logger log = LoggerFactory.getLogger(Runner.class);

  private static final String K8S_CLUSTER_SERVER_ADDR = "K8S_CLUSTER_SERVER_ADDR";

  private static final String K8S_CLUSTER_CERT = "K8S_CLUSTER_CERT";

  private static final String K8S_USER_KEY = "K8S_USER_KEY";

  private static final String K8S_USER_CERT = "K8S_USER_CERT";

  /**
   * Main entry point for the Metadata Ingest Operator. ## remember to add the following environment
   * variables: METADATA_OPERATOR_MODE=dev or prod and apply the following command: kubectl apply -f
   * ./target/classes/META-INF/fabric8/metadataingesttasks.org.zhejianglab.astro-v1.yml
   *
   * @param args
   * @throws IOException
   */
  public static void main(String[] args) throws IOException {
    log.info("Metadata Ingest Operator starting!");
    // Config config =
    //     new ConfigBuilder()
    //         .withMasterUrl(EnvUtil.getEnv(K8S_CLUSTER_SERVER_ADDR, "https://192.168.58.2:8443"))
    //         .withCaCertData(
    //             EnvUtil.getEnv(
    //                 K8S_CLUSTER_CERT,
    //
    // ""))
    //         .withClientCertData(
    //             EnvUtil.getEnv(
    //                 K8S_USER_KEY,
    //
    // ""))
    //         .withClientKeyData(
    //             EnvUtil.getEnv(
    //                 K8S_USER_CERT,
    //
    // ""))
    //         .build();
    // String kubeConfigPath = "/root/.kube/config2";
    // String kubeConfigContent = Files.readString(Paths.get(kubeConfigPath));
    // Config config2 = Config.fromKubeconfig(kubeConfigContent);

    Operator operator = new Operator(o -> o.withStopOnInformerErrorDuringStartup(false));

    operator.register(new MetadataOperatorFlinkReconciler());
    operator.register(new MetadataOperatorJavaReconciler());
    operator.start();

    log.info("Metadata Ingest Operator started.");

    HttpServer server = HttpServer.create(new InetSocketAddress(0), 0);
    server.createContext("/startup", new StartupHandler(operator));
    server.createContext("/healthz", new LivenessHandler(operator));
    server.setExecutor(null);
    server.start();

    log.info("Metadata Ingest Operator Healthy Probes started.");
  }
}
